/// VkImageUsageFlags
pub const ImageUsageFlags = packed struct(u32) {
    transfer_src: bool = false,
    transfer_dst: bool = false,
    sampled: bool = false,
    mini_khr: bool = false,
    _r4: u28 = 0,

    pub const transfer_all: ImageUsageFlags = .fromInt(0x3);
    pub const sampled_khr: ImageUsageFlags = .{ .sampled = true };

    pub inline fn toInt(self: ImageUsageFlags) u32 {
        return @bitCast(self);
    }
    pub inline fn fromInt(v: u32) ImageUsageFlags {
        return @bitCast(v);
    }
    pub inline fn merge(lhs: ImageUsageFlags, rhs: ImageUsageFlags) ImageUsageFlags {
        return .fromInt(lhs.toInt() | rhs.toInt());
    }
    pub inline fn intersect(lhs: ImageUsageFlags, rhs: ImageUsageFlags) ImageUsageFlags {
        return .fromInt(lhs.toInt() & rhs.toInt());
    }
    pub inline fn contains(lhs: ImageUsageFlags, rhs: ImageUsageFlags) bool {
        return lhs.toInt() & rhs.toInt() == rhs.toInt();
    }
    pub inline fn isEmpty(self: ImageUsageFlags) bool {
        return self.toInt() == 0;
    }
};

